try:
    print('>>> f = delattr')
    print('>>> x = ""')
    print('>>> y = b""')
    print('>>> f(x, y)')
    f = delattr
    x = ""
    y = b""
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
